package com.smartdoc.ai.provider;
import com.smartdoc.auth.CurrentUser; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import javax.servlet.http.HttpServletRequest; import java.util.*;
@RestController @RequestMapping("/api/ai") public class ProviderController { private final AiProviderService service; public ProviderController(AiProviderService s){service=s;} private static long user(HttpServletRequest r){return CurrentUser.from(r).getUserId();}
 @ExceptionHandler(NoSuchElementException.class) @ResponseStatus(HttpStatus.NOT_FOUND) public Map<String,String> missing(){return Map.of("message","Provider not found");}
 @ExceptionHandler(IllegalArgumentException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) public Map<String,String> invalid(){return Map.of("message","Invalid provider request");}
 @ExceptionHandler(IllegalStateException.class) @ResponseStatus(HttpStatus.CONFLICT) public Map<String,String> conflict(){return Map.of("message","Provider is referenced by routing");}
 @ExceptionHandler(ProviderHttpException.class) public ResponseEntity<Map<String,String>> providerError(ProviderHttpException e){return ResponseEntity.status(e.getStatus()).body(Map.of("code",e.getCode(),"message","Provider request failed"));}
 @GetMapping("/provider-presets") public AiProviderPreset[] presets(){return AiProviderPreset.values();} @GetMapping("/providers") public List<ProviderView> list(HttpServletRequest r){return service.list(user(r));} @GetMapping("/providers/{id}") public ProviderView get(HttpServletRequest r,@PathVariable long id){return service.get(user(r),id);} @PostMapping("/providers") @ResponseStatus(HttpStatus.CREATED) public ProviderView create(HttpServletRequest r,@RequestBody ProviderCreateRequest body){return service.create(user(r),body);} @PutMapping("/providers/{id}") public ProviderView update(HttpServletRequest r,@PathVariable long id,@RequestBody ProviderUpdateRequest body){return service.update(user(r),id,body);} @DeleteMapping("/providers/{id}/key") @ResponseStatus(HttpStatus.NO_CONTENT) public void clear(HttpServletRequest r,@PathVariable long id){service.clearKey(user(r),id);} @DeleteMapping("/providers/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(HttpServletRequest r,@PathVariable long id){service.delete(user(r),id);} @PostMapping("/providers/{id}/test") public Map<String,Object> test(HttpServletRequest r,@PathVariable long id){return service.test(user(r),id);} @GetMapping("/routing") public AiRoutingConfig routing(HttpServletRequest r){return service.routing(user(r));} @PutMapping("/routing") public AiRoutingConfig routing(HttpServletRequest r,@RequestBody RoutingUpdateRequest body){return service.updateRouting(user(r),body);} }
